import React, { useState } from "react";

export default function SafetyCheck() {
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [result, setResult] = useState("");
  const [loading, setLoading] = useState(false);

  const handleFetchLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLatitude(position.coords.latitude.toFixed(4));
          setLongitude(position.coords.longitude.toFixed(4));
        },
        (error) => {
          alert("Unable to fetch location. Please allow location access.");
          console.error(error);
        }
      );
    } else {
      alert("Geolocation is not supported by your browser.");
    }
  };

  const handleCheckSafety = async () => {
    if (!latitude || !longitude) {
      alert("Please enter or fetch your location first!");
      return;
    }

    try {
      setLoading(true);
      const response = await fetch("http://localhost:5000/api/safety/check", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          latitude: parseFloat(latitude),
          longitude: parseFloat(longitude),
        }),
      });

      if (!response.ok) throw new Error("Network response was not ok");

      const data = await response.json();
      setResult(data.message);
    } catch (error) {
      console.error("Error checking safety:", error);
      setResult("Error checking safety");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        height: "100vh",
        background: "linear-gradient(135deg, #ff9a3c, #ff6f00)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      <div
        style={{
          backgroundColor: "white",
          padding: "40px",
          borderRadius: "20px",
          boxShadow: "0px 10px 30px rgba(0,0,0,0.2)",
          textAlign: "center",
          width: "350px",
        }}
      >
        <h2 style={{ color: "#ff6f00", marginBottom: "20px" }}>
          Smart Tourist Safety
        </h2>

        <input
          type="number"
          placeholder="Enter Latitude"
          value={latitude}
          onChange={(e) => setLatitude(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            marginBottom: "10px",
            borderRadius: "10px",
            border: "1px solid #ccc",
          }}
        />
        <input
          type="number"
          placeholder="Enter Longitude"
          value={longitude}
          onChange={(e) => setLongitude(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            marginBottom: "15px",
            borderRadius: "10px",
            border: "1px solid #ccc",
          }}
        />

        <button
          onClick={handleFetchLocation}
          style={{
            width: "100%",
            padding: "10px",
            backgroundColor: "#ff9800",
            color: "white",
            border: "none",
            borderRadius: "10px",
            cursor: "pointer",
            marginBottom: "10px",
          }}
        >
          📍 Fetch My Location
        </button>

        <button
          onClick={handleCheckSafety}
          disabled={loading}
          style={{
            width: "100%",
            padding: "10px",
            backgroundColor: "#ff6f00",
            color: "white",
            border: "none",
            borderRadius: "10px",
            cursor: "pointer",
          }}
        >
          {loading ? "Checking..." : "Check Safety"}
        </button>

        {result && (
          <p
            style={{
              marginTop: "20px",
              fontWeight: "bold",
              color: result.includes("safe") ? "green" : "red",
              transition: "color 0.3s ease-in-out",
            }}
          >
            {result}
          </p>
        )}
      </div>
    </div>
  );
}
